import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1787084291000}'),i={name:"guide/security.md"};function n(s,e,d,l,c,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h1><p>This page is the prose version of <a href="https://github.com/ni-c/osm-mcp/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>.</p><p>The short version: there is no credential to steal by default, nothing this server can write, and the one thing worth thinking about is that your location queries travel to public services.</p><h2 id="trust-model" tabindex="-1">Trust model <a class="header-anchor" href="#trust-model" aria-label="Permalink to &quot;Trust model&quot;">​</a></h2><p>This server holds <strong>no credentials by default</strong> — it talks to public, read-only OpenStreetMap services. All 11 tools are read-only and carry the MCP <code>readOnlyHint</code> annotation; the server cannot modify OpenStreetMap data, because the editing API is simply not wired up. There is no write mode to switch off.</p><p>The only optional secret is <code>ORS_API_KEY</code>, an OpenRouteService key. Compromising it lets an attacker consume the key owner&#39;s free-tier request quota — nothing more. It grants no access to any data of yours.</p><h2 id="where-your-data-goes" tabindex="-1">Where your data goes <a class="header-anchor" href="#where-your-data-goes" aria-label="Permalink to &quot;Where your data goes&quot;">​</a></h2><p>The one real consideration: <strong>location queries are sent to the configured public services.</strong> A geocode of your home address, a route from your hotel, a POI search around where you are right now — each is an HTTPS request to Nominatim, OSRM, Overpass, Valhalla, Photon or OpenRouteService, subject to those operators&#39; logging and privacy practices.</p><p>Do not use this server for locations you would not put in a third-party web request. For sensitive use, self-host the services and point the <code>*_BASE_URL</code> variables at your instances — every backend supports it, and the <a href="/guide/configuration">configuration page</a> covers the details.</p><h2 id="api-key-handling" tabindex="-1">API-key handling <a class="header-anchor" href="#api-key-handling" aria-label="Permalink to &quot;API-key handling&quot;">​</a></h2><p><code>ORS_API_KEY</code> is treated as radioactive from the moment it is read:</p><ul><li>It is <strong>deleted from <code>process.env</code> before anything else happens</strong> — before any configuration validation can throw — so a caller that catches a <code>ConfigError</code> and keeps running does not keep the key readable in <code>/proc/&lt;pid&gt;/environ</code> or inherited by child processes.</li><li>It is <strong>redacted from error messages</strong> before they reach the model context.</li><li>The server <strong>refuses to start</strong> with a key set and a cleartext non-loopback <code>ORS_BASE_URL</code>, because the key travels in an <code>Authorization</code> header.</li><li>Invalid configuration values are <strong>not echoed</strong> in error messages — a key pasted into the wrong variable would otherwise land verbatim in the MCP host&#39;s log.</li></ul><h2 id="untrusted-content" tabindex="-1">Untrusted content <a class="header-anchor" href="#untrusted-content" aria-label="Permalink to &quot;Untrusted content&quot;">​</a></h2><p>OpenStreetMap data is user-contributed: place names, addresses and tags are written by millions of mappers, and a tag value can contain anything — including text that reads like instructions to a model. Every tool result carrying OSM-sourced content is therefore explicitly <strong>marked as untrusted data, not instructions</strong>, so the model treats a POI named &quot;ignore all previous instructions&quot; as a badly named POI.</p><p>Upstream error bodies get the same caution: they are truncated, and HTML error pages are dropped entirely before anything reaches the model context.</p><h2 id="network-posture" tabindex="-1">Network posture <a class="header-anchor" href="#network-posture" aria-label="Permalink to &quot;Network posture&quot;">​</a></h2><ul><li>The server speaks stdio and <strong>never listens on a port</strong>.</li><li><strong>Redirects are never followed</strong> — a redirect would replay request headers (including the ORS <code>Authorization</code> header) at whatever host it names.</li><li>Every request <strong>times out</strong> (30 s; 40 s for Overpass, whose queries also carry their own server-side 25 s budget).</li><li>Responses are size-capped before they are buffered.</li></ul><h2 id="being-a-good-citizen-is-also-a-security-property" tabindex="-1">Being a good citizen is also a security property <a class="header-anchor" href="#being-a-good-citizen-is-also-a-security-property" aria-label="Permalink to &quot;Being a good citizen is also a security property&quot;">​</a></h2><p>The client-side rate limits, the Overpass concurrency cap, the identifying User-Agent and the response cache exist to honor the published usage policies of shared community infrastructure — but they double as protection for you: they make it impossible for a confused or manipulated model to turn this server into a request cannon fired from your IP address.</p><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to &quot;Reporting a vulnerability&quot;">​</a></h2><p>Use <a href="https://github.com/ni-c/osm-mcp/security/advisories/new" target="_blank" rel="noreferrer">private vulnerability reporting</a>. Do not open a public issue for an unpatched vulnerability, and do not include real credentials, tokens, hostnames or private configuration in a report. You can expect an initial response within a week; fixes ship as a new release with a CHANGELOG note. Only the latest release and the current <code>main</code> branch receive security fixes.</p>',21)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
